package com.prismora.compat;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;
class PackContractTest {
 @Test void activeComputeSuffixesAreNotSilentlyDropped()throws Exception{var f=LegacyTranslatorTest.files();f.put("shaders/final_a.csh","void main(){}".getBytes(StandardCharsets.UTF_8));var p=LegacyPack.inspect("test",f);var error=assertThrows(java.io.IOException.class,()->LegacyAdapter.prepare(p.snapshot(),Map.of(),"minecraft:overworld"));assertTrue(error.getMessage().contains("active compute stage"));}
 @Test void conditionalProgramsAreEvaluatedByTheRuntimeAdapter()throws Exception{var f=LegacyTranslatorTest.files();f.put("shaders/composite.vsh",f.get("shaders/final.vsh"));f.put("shaders/composite.fsh",f.get("shaders/final.fsh"));f.put("shaders/shaders.properties","#if EXPOSURE > 1.0\nprogram.world0/composite.enabled=true\n#else\nprogram.world0/composite.enabled=false\n#endif".getBytes(StandardCharsets.UTF_8));var p=LegacyPack.inspect("test",f);var low=LegacyAdapter.prepare(p.snapshot(),Map.of("EXPOSURE","0.5"),"minecraft:overworld");var high=LegacyAdapter.prepare(p.snapshot(),Map.of("EXPOSURE","2.0"),"minecraft:overworld");assertEquals(1,low.manifest().getAsJsonArray("passes").size());assertEquals(2,high.manifest().getAsJsonArray("passes").size());}
 @Test void fallbackProgramsAndDimensionStageInheritanceAreResolved()throws Exception{var f=LegacyPackTest.fixture();f.put("shaders/gbuffers_textured.vsh","void main(){}".getBytes(StandardCharsets.UTF_8));f.put("shaders/gbuffers_textured.fsh","void main(){}".getBytes(StandardCharsets.UTF_8));f.put("shaders/world-1/gbuffers_textured.fsh","void main(){int nether=1;}".getBytes(StandardCharsets.UTF_8));var pack=LegacyPack.inspect("test",f);var contract=new PackContract(pack,Map.of(),Map.of(),"minecraft:the_nether");var program=contract.resolve("gbuffers_entities_glowing").orElseThrow();assertEquals("gbuffers_textured",program.name());assertEquals("shaders/gbuffers_textured.vsh",program.vertex());assertEquals("shaders/world-1/gbuffers_textured.fsh",program.fragment());assertTrue(contract.resolve("gbuffers_clouds").isEmpty());}
 @Test void inactiveMrtDirectivesDoNotRejectAColorOnlyShader()throws Exception{var f=LegacyTranslatorTest.files();String fs=new String(f.get("shaders/final.fsh"),StandardCharsets.UTF_8);f.put("shaders/final.fsh",("#if 0\n/* DRAWBUFFERS:01 */\n#endif\n"+fs).getBytes(StandardCharsets.UTF_8));assertDoesNotThrow(()->LegacyAdapter.prepare(LegacyPack.inspect("test",f).snapshot(),Map.of(),"minecraft:overworld"));}
}
